0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4866,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 18.73\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T622,"])self.__next_f.push([1,"The constitutional position of a living entity, represented by Arjuna, is that he has to act according to the order of the Supreme Lord. He is meant for self-discipline. Śrī Caitanya Mahāprabhu says that the actual position of the living entity is that of eternal servant of the Supreme Lord. Forgetting this principle, the living entity becomes conditioned by material nature, but in serving the Supreme Lord he becomes the liberated servant of God. The living entity’s constitutional position is to be a servitor; he has to serve either the illusory māyā or the Supreme Lord. If he serves the Supreme Lord he is in his normal condition, but if he prefers to serve the illusory, external energy, then certainly he will be in bondage. In illusion the living entity is serving in this material world. He is bound by his lust and desires, yet he thinks of himself as the master of the world. This is called illusion. When a person is liberated, his illusion is over, and he voluntarily surrenders unto the Supreme to act according to His desires. The last illusion, the last snare of māyā to trap the living entity, is the proposition that he is God. The living entity thinks that he is no longer a conditioned soul, but God. He is so unintelligent that he does not think that if he were God, then how could he be in doubt? That he does not consider. So that is the last snare of illusion. Actually to become free from the illusory energy is to understand Kṛṣṇa, the Supreme Personality of Godhead, and agree to act according to His order."])self.__next_f.push([1,"26:T5af,"])self.__next_f.push([1,"Kṛṣṇa consciousness is acting according to Kṛṣṇa’s order. A conditioned soul, illusioned by the external energy of matter, does not know that the Supreme Lord is the master who is full of knowledge and who is the proprietor of everything. Whatever He desires He can bestow upon His devotees; He is the friend of everyone, and He is especially inclined to His devotee. He is the controller of this material nature and of all living entities. He is also the controller of inexhaustible time, and He is full of all opulences and all potencies. The Supreme Personality of Godhead can even give Himself to the devotee. One who does not know Him is under the spell of illusion; he does not become a devotee, but a servitor of māyā. Arjuna, however, after hearing Bhagavad-gītā from the Supreme Personality of Godhead, became free from all illusion. He could understand that Kṛṣṇa was not only his friend but the Supreme Personality of Godhead. And he understood Kṛṣṇa factually. So to study Bhagavad-gītā is to understand Kṛṣṇa factually. When a person is in full knowledge, he naturally surrenders to Kṛṣṇa. When Arjuna understood that it was Kṛṣṇa’s plan to reduce the unnecessary increase of population, he agreed to fight according to Kṛṣṇa’s desire. He again took up his weapons – his arrows and bow – to fight under the order of the Supreme Personality of Godhead."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4866,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"73\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 73\",\"advanced_view_url_path\":\"/en/library/bg/18/advanced-view/#bb4256\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/18/73/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/18/73/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/18/73/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/18/73/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/18/73/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/18/73/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/18/73/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/18/73/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/